(function(){
  var root=document.body.dataset.root||"", nav=document.getElementById("nav"), q=document.getElementById("q");
  var here=location.pathname.replace(/index\.html$/,"");
  function esc(s){return s.replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
  function draw(f){
    f=(f||"").trim().toLowerCase(); var h="";
    LC_NAV.forEach(function(t){
      var items=t.p.filter(function(p){return !f||(p[0]+" "+p[1]).toLowerCase().indexOf(f)>=0});
      if(!items.length)return;
      var open=f||here.indexOf("/t/"+t.s+"/")>=0||items.some(function(p){return here.indexOf("/p/"+p[2]+"/")>=0});
      h+='<details'+(open?" open":"")+'><summary><span>'+esc(t.t)+'</span><small>'+items.length+'</small></summary><ul>';
      items.forEach(function(p){var u=root+"p/"+p[2]+"/";var on=here.indexOf("/p/"+p[2]+"/")>=0;
        h+='<li><a href="'+u+'"'+(on?' class="on"':"")+' title="'+esc(p[1])+'"><span class="d d'+p[3]+'"></span>'+esc(p[1])+'</a></li>'});
      h+="</ul></details>";
    });
    nav.innerHTML=h||'<p style="color:#7c776c;padding:0 10px"><span class="zh">找不到符合的題目</span><span class="en">No matching problems</span></p>';
  }
  draw(); q.addEventListener("input",function(){draw(q.value)});
  var on=nav.querySelector("a.on"); if(on) on.scrollIntoView({block:"center"});
})();
